mapper.insert:
INSERT INTO users (
    user_id
  , password
  , user_name
  , email
  , phone
  , postal_code
  , address_line1
  , address_line2
  , birth_date
  , gender
  , status
  , agree_terms
  , agree_privacy
  , agree_marketing
  , ins_dt
  , upt_dt
  , login_fail_cnt
) VALUES (
    #{userId}
  , #{password}
  , #{userName}
  , #{email}
  , #{phone}
  , #{postalCode}
  , #{addressLine1}
  , #{addressLine2}
  , #{birthDate}
  , #{gender}
  , 'A'
  , CAST(#{agreeTerms} AS BOOLEAN)
  , CAST(#{agreePrivacy} AS BOOLEAN)
  , CAST(#{agreeMarketing} AS BOOLEAN)
  , NOW()
  , NOW()
  , 0
)

mapper.update:
UPDATE users
   SET user_name = #{userName}
     , email = #{email}
     , phone = #{phone}
     , postal_code = #{postalCode}
     , address_line1 = #{addressLine1}
     , address_line2 = #{addressLine2}
     , birth_date = #{birthDate}
     , gender = #{gender}
     , upt_dt = NOW()
 WHERE user_id = #{userId}

UPDATE users
   SET last_login_dt = NOW()
 WHERE user_id = #{userId}

UPDATE users
   SET login_fail_cnt = COALESCE(login_fail_cnt, 0) + 1
 WHERE user_id = #{userId}

UPDATE users
   SET status = #{status}
     , upt_dt = NOW()
 WHERE user_id = #{userId}

UPDATE users
   SET password = #{password}
     , upt_dt = NOW()
 WHERE user_id = #{userId}

mapper.insert:
INSERT INTO user_terms_consents (
    user_seq
  , terms_type
  , terms_version
  , is_required
  , is_agreed
  , agreed_at
  , consent_source
  , consent_ip
  , user_agent
  , created_at
) VALUES (
    #{userSeq}
  , #{termsType}
  , #{termsVersion}
  , CAST(#{isRequired} AS BOOLEAN)
  , CAST(#{isAgreed} AS BOOLEAN)
  , NOW()
  , #{consentSource}
  , #{consentIp}
  , #{userAgent}
  , NOW()
)
